#include <stddef.h>
#include <stdint.h>

void stream_process(const uint8_t* data, size_t len, void (*cb)(const char*, size_t, void*), void* user) {
  size_t i, n = (len + 63) / 64;
  for (i = 0; i < n; ++i) {
    size_t offset = i * 64;
    size_t chunk_len = (offset + 64 <= len) ? 64 : (len - offset);
    cb((const char*)(data + offset), chunk_len, user);
  }
}
